#include "pci.h"
static uint32_t cfg_read32(uintptr_t base,uint8_t b,uint8_t d,uint8_t f,uint8_t r){volatile uint32_t*p=(volatile uint32_t*)(base+((uintptr_t)b<<20)+((uintptr_t)d<<15)+((uintptr_t)f<<12)+r);return *p;}
mc_status_t pci_scan_ecam(uintptr_t base,uint8_t bs,uint8_t be,pci_device_t*out,size_t cap,size_t*count){if(!out||!count||bs>be)return MC_EINVAL;*count=0;for(uint16_t b=bs;b<=be;b++)for(uint8_t d=0;d<32;d++)for(uint8_t f=0;f<8;f++){uint32_t id=cfg_read32(base,b,d,f,0);if(id==0xffffffffu||id==0)continue;if(*count>=cap)return MC_ENOMEM;uint32_t cls=cfg_read32(base,b,d,f,8);pci_device_t*x=&out[(*count)++];x->vendor_id=id&0xffff;x->device_id=id>>16;x->bus=b;x->slot=d;x->function=f;x->class_code=(cls>>24)&255;x->subclass=(cls>>16)&255;for(int i=0;i<6;i++)x->bars[i]=cfg_read32(base,b,d,f,0x10+i*4);}return MC_OK;}
